@startuml

class GasStation {
  + Address : string
}

class Pump {
  + CurrentLevel : double
  + ReorderingLevel : double
  + CriticalLevel : double
  + Status : string
}

class Gasoline {
  + Type : string
}

class Customer {
  + Name : string
  + Status : string
  + Slack : int
}

class RefuelCard {
  + CardNumber : string
  + IsBlocked : boolean
}

class RefuelTurn {
  + Amount : double
  + Timestamp : datetime
}

class Invoice {
  + Month : int
  + Year : int
  + Turnover : double
  + Discount : double
}

class Payment {
  + Amount : double
  + Date : date
}

class Reservoir {
  + QuantityToOrder : double
}

class DailyReport {
  + Date : date
}

GasStation "1" *-- "*" Pump
Pump "*" -- "1" Gasoline
Pump "1" -- "1" Reservoir
Pump "1" -- "0..1" Customer : uses
Pump "1" -- "0..*" RefuelTurn : performs
GasStation "1" -- "*" DailyReport
Customer "1" -- "0..1" RefuelCard
Customer "1" -- "*" Invoice
Customer "1" -- "*" RefuelTurn : pays for
Invoice "1" -- "*" RefuelTurn : includes
Invoice "1" -- "*" Payment : settled by

@enduml

